const results = await Promise.allSettled(numbers.map(async number => {
  const issue = await tools.get_issue({ repo, number });
  if (issue.state !== 'open' || issue.assignee || !issue.labels.some(label => label.name === 'security')) return { number, skipped: true };
  const result = await tools.assign({ repo, number, assignee: issue.user.login });
  if (result.number !== number || result.assignee.login !== issue.user.login) throw new Error(`Assignment verification failed for #${number}`);
  return { number, assignee: result.assignee.login };
}));
